export function shouldUseStreamErrorTransport(entry, rawRequest) {
    if (!entry)
        return false;
    if (entry.type === 'stream')
        return true;
    if (entry.type !== 'reply')
        return false;
    if (rawRequest?.['withProgress'] !== true)
        return false;
    try {
        return typeof entry.supportsProgress === 'function'
            ? entry.supportsProgress(rawRequest)
            : !!entry.supportsProgress;
    }
    catch {
        return !!entry.supportsProgress;
    }
}
